  const SCAT=EV.map((e,i)=>{ const a=i*2.399; const r=90+((i*53)%160);
    return [W*0+Math.cos(a)*r+300, 200+Math.sin(a)*r*0.55]; });
  const TL=(t,e)=>[150+t*((W-300)/11), H*0.62+e*22-44];
  const WINB=[2.5,5.5,8.5];
